function e($s):string{return studioEsc($s);}
function ext($url,$label):string{
 if(!is_string($url)||!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https')return '';
 return '<a class="book-link" href="'.e($url).'" target="_blank" rel="noopener noreferrer">'.e($label).' ↗</a>';
}
$map=[];foreach($data['books'] as $b)$map[$b['id']]=$b;
foreach($data['archives'] as $a)$map['@'.$a['id']]=$a;
$categories=array_values(array_unique(array_column($data['books'],'category')));
